INSERT INTO catalogue_listing (id, provider_org_id, country_code, region_id, category, title, description, languages, min_age, difficulty, accessibility, min_party, max_party, duration_minutes, service_tier, status, image_url) VALUES
  ('1c9a0001-0000-0000-0000-000000000001', '1a9a0001-0000-0000-0000-000000000001', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Ouzoud Falls Day Trip', 'A full-day guided walk to the 110m Ouzoud waterfalls with wild monkeys and a traditional lunch.', ARRAY['en','fr','es','ary-Latn','ber'], 8, 2, '{}', 1, 12, 480, 2, 'active', 'https://images.pexels.com/photos/6545708/pexels-photo-6545708.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('2c9a0002-0000-0000-0000-000000000002', '4a9a0004-0000-0000-0000-000000000004', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Pottery Wheel Workshop', 'Learn to throw clay on a traditional potter''s wheel with a master artisan in the medina.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 1, '{}', 1, 6, 120, 1, 'active', 'https://images.pexels.com/photos/32422996/pexels-photo-32422996.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('3c9a0003-0000-0000-0000-000000000003', '4a9a0004-0000-0000-0000-000000000004', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Henna Art Workshop', 'Discover the ancient art of Moroccan henna with a skilled naqasha (henna artist).', ARRAY['en','fr','es','ary-Latn'], 8, 1, '{}', 1, 8, 90, 1, 'active', 'https://images.pexels.com/photos/27151466/pexels-photo-27151466.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('4c9a0004-0000-0000-0000-000000000004', '3a9a0003-0000-0000-0000-000000000003', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Marrakech Food Tour', 'A 3-hour evening food walk through Jemaa el-Fnaa and the souks, tasting 8 local specialities.', ARRAY['en','fr','ary-Latn','ber'], 10, 1, '{}', 1, 10, 180, 2, 'active', 'https://images.pexels.com/photos/36984667/pexels-photo-36984667.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('5c9a0005-0000-0000-0000-000000000005', '2a9a0002-0000-0000-0000-000000000002', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Riad Zitoun Suite (per night)', 'A beautifully restored riad suite in the Marrakech medina with breakfast and rooftop terrace.', ARRAY['en','fr','es','ary-Arab','ber'], 0, 1, '{}', 1, 4, 1440, 3, 'active', 'https://images.pexels.com/photos/15531322/pexels-photo-15531322.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('6c9a0006-0000-0000-0000-000000000006', '4a9a0004-0000-0000-0000-000000000004', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Carpet Weaving Workshop', 'Learn traditional Berber carpet weaving techniques on a wooden loom with master weavers.', ARRAY['en','fr','es','ary-Latn','ber'], 12, 1, '{}', 1, 6, 150, 1, 'active', 'https://images.pexels.com/photos/28582586/pexels-photo-28582586.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('7c9a0007-0000-0000-0000-000000000007', '3a9a0003-0000-0000-0000-000000000003', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Moroccan Mint Tea Ceremony', 'Learn the art of brewing and pouring Moroccan mint tea, with pastries, on a rooftop terrace.', ARRAY['en','fr','es','ary-Latn','ber'], 5, 1, '{}', 1, 12, 60, 1, 'active', 'https://images.pexels.com/photos/30906051/pexels-photo-30906051.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('8c9a0008-0000-0000-0000-000000000008', 'b1111111-0000-0000-0000-000000000001', 'MA', 'a1111111-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Majorelle Garden & Berber Museum Tour', 'A guided tour of the Jardin Majorelle and the Berber Museum, exploring Yves Saint Laurent''s legacy.', ARRAY['en','fr','es','ary-Latn'], 6, 1, '{}', 1, 15, 120, 2, 'active', 'https://images.pexels.com/photos/22711558/pexels-photo-22711558.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('9c9a0009-0000-0000-0000-000000000009', '5a9a0005-0000-0000-0000-000000000005', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Luxury Desert Camp (per night)', 'A luxury tented camp at the foot of the Erg Chebbi dunes with dinner, breakfast and stargazing.', ARRAY['en','fr','es','it','ary-Latn','ber'], 0, 1, '{}', 1, 6, 1440, 4, 'active', 'https://images.pexels.com/photos/9349466/pexels-photo-9349466.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('ac9a0010-0000-0000-0000-000000000010', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'desert_experience', 'Nomadic Desert Survival Experience', 'Spend a day with a nomadic family learning desert survival: finding water, building shelter, baking bread in sand.', ARRAY['en','fr','es','ary-Latn','ber'], 12, 3, '{}', 1, 8, 480, 2, 'active', 'https://images.pexels.com/photos/18742776/pexels-photo-18742776.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('bc9a0011-0000-0000-0000-000000000011', '6a9a0006-0000-0000-0000-000000000006', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'desert_experience', 'Sunset Camel Trek to Dunes', 'A 2-hour camel trek from Merzouga village to the top of the Erg Chebbi dunes for sunset.', ARRAY['en','fr','es','it','ary-Latn','ber'], 5, 2, '{}', 1, 10, 120, 2, 'active', 'https://images.pexels.com/photos/28356796/pexels-photo-28356796.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('cc9a0012-0000-0000-0000-000000000012', 'b3333333-0000-0000-0000-000000000003', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Berber Tagine Dinner Under the Stars', 'A traditional Berber dinner cooked over coals, served on carpets under the desert sky.', ARRAY['en','fr','ary-Latn','ber'], 5, 1, '{}', 1, 12, 120, 2, 'active', 'https://images.pexels.com/photos/2287528/pexels-photo-2287528.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('dc9a0013-0000-0000-0000-000000000013', '5a9a0005-0000-0000-0000-000000000005', 'MA', 'a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Sandboarding on Erg Chebbi', 'Rent a sandboard and slide down the golden dunes of Erg Chebbi. Instruction included.', ARRAY['en','fr','es','ary-Latn'], 8, 2, '{}', 1, 8, 90, 1, 'active', 'https://images.pexels.com/photos/12378901/pexels-photo-12378901.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('ec9a0014-0000-0000-0000-000000000014', '7a9a0007-0000-0000-0000-000000000007', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Fès Medina & Tannery Tour', 'A half-day guided walk through the 9,000 alleys of Fès el-Bali, including the famous Chouara tannery.', ARRAY['en','fr','es','it','ary-Latn','ber'], 8, 2, '{}', 1, 12, 240, 3, 'active', 'https://images.pexels.com/photos/38112348/pexels-photo-38112348.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('fc9a0015-0000-0000-0000-000000000015', '9a9a0009-0000-0000-0000-000000000009', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Fès Pottery & Zellige Workshop', 'Work with master Fassi artisans to create your own pottery and zellige tile mosaic.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 1, '{}', 1, 6, 180, 2, 'active', 'https://images.pexels.com/photos/18373966/pexels-photo-18373966.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('1c9a0016-0000-0000-0000-000000000016', '8a9a0008-0000-0000-0000-000000000008', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Dar Attamani Suite (per night)', 'A traditional Fassi guesthouse suite with breakfast on the rooftop terrace overlooking the medina.', ARRAY['en','fr','es','ary-Arab','ber'], 0, 1, '{}', 1, 4, 1440, 3, 'active', 'https://images.pexels.com/photos/10573397/pexels-photo-10573397.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('2c9a0017-0000-0000-0000-000000000017', 'b6666666-0000-0000-0000-000000000006', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Fès Royal Feast Dinner', 'A multi-course royal Moroccan dinner in a restored Fassi palace, with live Andalusian music.', ARRAY['en','fr','es','ary-Latn','ber'], 10, 1, '{}', 2, 20, 150, 3, 'active', 'https://images.pexels.com/photos/31497982/pexels-photo-31497982.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('3c9a0018-0000-0000-0000-000000000018', '9a9a0009-0000-0000-0000-000000000009', 'MA', 'a3333333-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Leather Dyeing Workshop', 'Visit the Chouara tannery and learn the ancient art of natural leather dyeing with a master tanner.', ARRAY['en','fr','es','ary-Latn','ber'], 12, 2, '{}', 1, 6, 120, 2, 'active', 'https://images.pexels.com/photos/38112326/pexels-photo-38112326.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('4c9a0019-0000-0000-0000-000000000019', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Kitesurf Course (3 days)', 'A 3-day kitesurf course for beginners on Essaouira bay with certified instructors and all gear included.', ARRAY['en','fr','es','ary-Latn'], 12, 3, '{}', 1, 6, 180, 2, 'active', 'https://images.pexels.com/photos/18554039/pexels-photo-18554039.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('5c9a0020-0000-0000-0000-000000000020', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Surf Lesson for Beginners', 'A 2-hour beginner surf lesson on Essaouira beach with wetsuit and board included.', ARRAY['en','fr','ary-Latn'], 8, 2, '{}', 1, 8, 120, 1, 'active', 'https://images.pexels.com/photos/7835701/pexels-photo-7835701.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('6c9a0021-0000-0000-0000-000000000021', 'ba9a0011-0000-0000-0000-000000000011', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Riad Mogador Seafront Room (per night)', 'A seafront riad room within the Essaouira ramparts, with breakfast and ocean views.', ARRAY['en','fr','es','ary-Arab','ber'], 0, 1, '{}', 1, 4, 1440, 2, 'active', 'https://images.pexels.com/photos/25254928/pexels-photo-25254928.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('7c9a0022-0000-0000-0000-000000000022', 'aa9a0010-0000-0000-0000-000000000010', 'MA', 'a5555555-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Essaouira Medina & Ramparts Walk', 'A guided walk through the Portuguese ramparts, medina and artisan workshops of Essaouira.', ARRAY['en','fr','es','ary-Latn'], 8, 1, '{}', 1, 12, 150, 2, 'active', 'https://images.pexels.com/photos/25254928/pexels-photo-25254928.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('8c9a0023-0000-0000-0000-000000000023', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'tour', 'Hassan II Mosque Guided Tour', 'A guided tour of the Hassan II Mosque, one of the largest mosques in the world, with its glass floor over the sea.', ARRAY['en','fr','es','it','ary-Latn'], 6, 1, '{}', 1, 20, 90, 3, 'active', 'https://images.pexels.com/photos/2404046/pexels-photo-2404046.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
