  ('ac9a0025-0000-0000-0000-000000000025', 'ea9a0014-0000-0000-0000-000000000014', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Casablanca Street Food Walk', 'A 3-hour evening food walk through Casablanca market and the old medina, tasting 7 local dishes.', ARRAY['en','fr','ary-Latn','ber'], 10, 2, '{}', 1, 10, 180, 2, 'active', 'https://images.pexels.com/photos/36984667/pexels-photo-36984667.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
